"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["7891"],{46993(e){e.exports=JSON.parse('{"id":"F160","slug":"break-even-analysis","name":"Break-Even Analysis","subject":"Corporate Finance","section":"Capital Budgeting","topic":"Sensitivity, scenario and break-even analysis","level":"Beginner","aliases":["break even units","accounting break-even","contribution margin","break-even point"],"formula":{"latex":"Q^{*}=\\\\frac{FC}{P-VC}","also":[],"text":"Break-even quantity = Fixed costs / (Price - Variable cost per unit)"},"symbols":[{"symbol":"Q*","meaning":"Number of units that must be sold to cover all costs","unit":"units"},{"symbol":"FC","meaning":"Fixed costs for the period","unit":"money"},{"symbol":"P","meaning":"Selling price per unit","unit":"money per unit"},{"symbol":"VC","meaning":"Variable cost per unit","unit":"money per unit"}],"when_to_use":"Use it to find the sales volume at which the project makes neither a profit nor a loss. Compare it with your realistic sales forecast to see how much room for error there is.","worked_example":{"problem":"A product sells for 25. It costs 15 per unit to make and the company has fixed costs of 50,000 a year. How many units must it sell to break even, and what if it expects to sell 7,000?","inputs":{"fc":50000,"p":25,"vc":15,"q":7000},"steps":[{"label":"Contribution margin per unit = P - VC","working":"25-15","value":"10.00"},{"label":"Break-even units = FC / contribution margin","working":"50000 / 10","value":"5,000"},{"label":"Break-even sales = break-even units x P","working":"5000 x 25","value":"125,000.00"},{"label":"Profit at expected sales = (P - VC) x Q - FC","working":"10 x 7000-50000","value":"20,000.00"},{"label":"Margin of safety = (Q - break-even) / Q","working":"(7000-5000) / 7000","value":"28.57%"}],"answer":"Break-even is 5,000 units, or 125,000.00 in sales. At 7,000 units the profit is 20,000.00, a margin of safety of 28.57%."},"calculator":{"available":true,"inputs":[{"id":"fc","label":"Fixed costs","unit":"money","type":"number","default":50000,"hint":""},{"id":"p","label":"Price per unit","unit":"money","type":"number","default":25,"hint":""},{"id":"vc","label":"Variable cost per unit","unit":"money","type":"number","default":15,"hint":""},{"id":"q","label":"Expected sales (units)","unit":"units","type":"number","default":7000,"hint":""}],"checks":[{"expr":"p>vc","message":"The price must be higher than the variable cost per unit, or no volume can break even."}],"steps":[{"id":"cm","label":"Contribution margin per unit = P - VC","expr":"p-vc","format":"money"},{"id":"be","label":"Break-even units = FC / contribution margin","expr":"fc/cm","format":"num0"},{"id":"rev","label":"Break-even sales = break-even units x P","expr":"be*p","format":"money"},{"id":"profit","label":"Profit at expected sales = (P - VC) x Q - FC","expr":"cm*q-fc","format":"money"},{"id":"mos","label":"Margin of safety = (Q - break-even) / Q","expr":"(q-be)/q","format":"pct2"}],"results":["be","rev","profit"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"be":5000,"rev":125000,"profit":20000}},"finder":{"finds":"Sales needed to cover costs","needs":"Fixed costs, price, variable cost, expected sales"},"related":[{"slug":"degree-of-operating-leverage","name":"Degree of Operating Leverage (DOL)"},{"slug":"profit-margins","name":"Profit Margins"}],"related_ids":["F173","F066"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msup><mi>Q</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2217</mo></msup><mo>=</mo><mfrac><mrow><mi>F</mi><mi>C</mi></mrow><mrow><mi>P</mi><mo>\u2212</mo><mi>V</mi><mi>C</mi></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">Q^{*}=\\\\frac{FC}{P-VC}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"bootstrap-spot-rates","name":"Bootstrapping Spot Rates from Par Yields"},"next":{"slug":"brownian-motion-facts","name":"Brownian Motion Probabilities"},"lesson":{"name":"Lesson 7 \xb7 Variance and valuation","to":"/courses/financial-data-to-insight/variance-and-valuation"},"total":522}')}}]);